BEGIN
  PERFORM coaching.apply_candidate_exercise_card_v1($card_1_payload${"migrationKey":"724_coaching_linear_deceleration_stick_candidate_materialization","researchVersion":"2026-07-25.3","definition":{"facilityId":1,"legacyExerciseId":155,"preserveLegacyExerciseId":true,"slug":"jog-to-stick-linear-deceleration","canonicalName":"Submaximal Linear Deceleration to Stick","displayName":"Submaximal Linear Deceleration to Stick","aliases":["Jog-to-Stick Linear Deceleration","Sprint-to-Stick Deceleration","5-Yard Accel to Decel Stick","Linear Deceleration Stop Eccentric Stick","Sprint-to-Balance Deceleration"],"description":"Build through a declared 5–10 metre submaximal linear approach, initiate braking before the marked brake zone, use multiple controlled deceleration contacts, stop inside the protected finish zone, own a balanced bilateral athletic stick for the declared hold, then reset by walking. One repetition contains one approach, one planned linear stop, one terminal stick, and no turn or reacceleration.","familyKey":"submaximal_linear_deceleration_terminal_stick","schemaVersion":"2.0.0","cardVersion":3,"status":"review","identityContract":"declared_submaximal_linear_approach_multiple_braking_contacts_bilateral_terminal_stick_without_turn_or_reacceleration","confidence":{"content":84,"scoring":62,"media":50},"movementPatterns":["locomote","decelerate","land","brace"],"bodyRegions":["foot","ankle","calf","knee","thigh","hip","core"],"requiredEquipment":["cones","safe_finish_zone","15_to_30_metre_clear_lane"],"optionalEquipment":["timing_gates","video"],"environment":{"surface":"clear, level, dry, high-traction non-slip lane with a marked approach, braking zone, finish zone, and protected runoff","space":"one protected 15–30 metre lane with no cross traffic and a visible coach sightline to braking contacts and finish","stationCapacity":1,"inspection":["surface traction, debris, weather, footwear, cones, lane separation, and runoff","declared approach, braking, finish,