tillSequenceRequired":true,"audioDescriptionRequired":true,"humanReviewRequired":true,"approvedMediaAvailable":false}},"coachSupport":{"observationChecklist":["exact approach, brake zone, finish zone, declared entry speed, and no-turn boundary","penultimate and braking contacts, foot placement, posture, knee/trunk control, final balance, and side asymmetry","surface, symptoms, valid stops, rest, and cumulative braking exposure"],"faultCorrections":{"late_braking":"shorten or slow the approach and restore braking before the marked zone","reaching_or_hard_stop":"reduce entry speed and rehearse several smaller braking contacts","line_overrun":"enlarge the finish zone or shorten the approach; do not chase speed","collapse_or_imbalance":"stop the effort, reduce demand only if control returns, otherwise select another reviewed task after revalidation"},"demonstrationPlan":["show the protected approach, brake zone, finish zone, walk-back route, and stop signal","show a lower-speed valid repetition with early braking and a quiet bilateral finish","show invalid late braking, one hard reaching stop, line overrun, collapse, and an added turn","confirm the athlete can state the zone, finish, and stop signal before speed rises"],"groupManagement":["use one athlete per protected lane and keep all waiting athletes behind the start","release an athlete only after the prior athlete clears the finish and walk-back route","record declared and actual approach context, valid stops, first fault, symptoms, rest, and total braking exposure","maintain coach sightline to approach, contacts, terminal stick, and stop signal"],"modificationDecisionTree":["if pain, giving way, slip, dizziness, unsafe lane, or communication failure occurs, stop and escalate under facility policy","if braking begins late or the finish is overrun, shorten or slow the approach and revalidate the exact profile","if controlled multi-step braking and balanced stick cannot be restored, end this task and select a separately reviewed option after full revalidation","if cue, direction, turn, reacceleration, timing protocol, or maximum-intent demand changes, do not substitute automatically; rerun identity, selection, budgets, logistics, duration, and validation"],"doNotUseWhen":["the intended task is a reactive cue, cut, turn, reacceleration, max-sprint deceleration, jump landing, or conditioning shuttle","surface, lane, symptoms, braking control, recovery, supervision, or communication is inadequate"]},"supportOperations":{"issueCategories":["surface_or_lane","entry_speed_or_braking","terminal_stick_or_balance","impact_or_fatigue","symptom_or_stop_event","dose_or_duration","substitution"],"supportEscalation":"Stop and escalate unresolved symptoms, slips, line overruns, collapse, imbalance, unsafe conditions, or a mismatch between the requested task and this exact submaximal linear brake-to-stick contract.","retentionPolicy":"Persist the versioned definition and exact variant, declared and actual approach context, brake and finish zones, valid stops, first fault, symptoms, rest, total braking exposure, substitution, stop reason, and generator/rendering versions under facility policy.","changeImpactPolicy":"Any change to approach, speed, braking-zone length, finish, hold, surface, cue, dose, timing, or substitute reruns selection, fatigue, impact, logistics, duration, substitutions, and validation."}},"sourceVariant":{"lookupKey":"contract-quarantine-jog-to-stick-linear-deceleration","archiveKey":"source-155-to-783-linear-deceleration-legacy-skeleton","displayName":"Linear Deceleration Legacy Skeleton — Sources 155–783","archiveReason":"The consolidated source rows omit a complete exact approach, braking, finish, dose, load, fatigue, support, alternate, and review contract."},"legacy":{"preserveArchived":true,"description":"Use a declared submaximal straight approach, begin braking before the zone, take multiple controlled steps, stop inside the zone, hold a balanced bilateral athletic stance, and walk back to reset.","defaultSets":2,"defaultReps":3,"defaultWorkSeconds":10,"defaultRestSeconds":75,"tempo":"easy build; brake before zone; multiple controlled steps; two-second quiet stick; walk-back reset","loadNote":"Bodyweight horizontal braking. Exact approach distance, entry speed, braking-zone length, finish, hold, rest, and total exposure are delivery-profile specific.","estimatedSecondsPerSet":120,"cardSummary":"Candidate submaximal linear braking-to-stick card with explicit lane, finish, no-turn, no-reacceleration, quality, and stop boundaries.","coachLanguage":"Protect the lane and quality; start with an easy approach and count only controlled early-brake stops.","athleteLanguage":"Slow before the cone, use several controlled steps, finish balanced, walk back, and report symptoms.","programmingLogic":{"sourceDisposition":"candidate_reauthored","selectable":false,"humanReviewRequired":true},"scalableVariables":["approach_distance","entry_speed","braking_zone_length","finish_zone","hold_seconds","repetitions","sets","rest","surface","feedback"]},"safety":{"riskLevel":3,"impactLevel":3,"requiresSpotting":false,"coachSupervision":"required","prerequisiteNotes":"Readiness is the exact declared approach, braking, finish, lane, surface, symptom, supervision, and recovery context—not a participant classification.","readinessChecks":["pain-free easy jogging and controlled bilateral stop","protected high-traction lane, marked brake/finish zones, and runoff","can follow the stop signal and demonstrate a lower-speed controlled stop","session braking, impact, and technical-fatigue budgets fit"],"stopSigns":["pain, giving way, slip, hard reaching stop, repeated line overrun, stumble, knee/trunk collapse, imbalance, unsafe lane, marked asymmetry, or participant stop request","fatigue that prevents early multi-step braking or a balanced bilateral finish"],"contraindications":["symptom, unsafe surface/lane, inadequate braking control, recovery, supervision, 